from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1]
m=json.loads((root/'assets/materials/manifest.json').read_text(encoding='utf-8'))
items=sorted([i for i in m['items'] if i['cat']=='sticker'],key=lambda i: i.get('pack')!='daily-stickers')
collections={c['id']:c['name'] for c in m['collections']}
new=sum(i.get('pack')=='daily-stickers' for i in items)
options='<option value="">全部主题</option><option value="base">基础素材</option>'+''.join(f'<option value="{escape(k)}">{escape(v)}</option>' for k,v in collections.items() if any(i.get('collection')==k for i in items))
cards=''.join(f'''<article data-theme="{escape(i.get('collection','base'))}" data-new="{str(i.get('pack')=='daily-stickers').lower()}"><img loading="lazy" width="180" height="170" src="../assets/materials/{escape(i['thumb'])}" alt="{escape(i['name'])}"><h2>{escape(i['name'])}</h2><p>{escape(' · '.join(i.get('tags',[])))}</p><a href="../?tab=library&amp;sticker={escape(i['id'])}">去素材库选中</a> · <a href="../assets/materials/{escape(i['file'])}" download>下载PNG</a></article>''' for i in items)
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>贴纸总览 · 手账工坊</title><style>body{{margin:0;background:#f6f2eb;color:#4b5048;font:15px/1.8 system-ui}}main{{max-width:1250px;margin:auto;padding:24px 18px}}a{{color:#55785e}}h1{{font-weight:500}}.filters{{display:flex;flex-wrap:wrap;gap:12px;align-items:center;background:#ede6db;padding:16px;border-radius:12px}}input,select{{max-width:100%;padding:9px;font:inherit;box-sizing:border-box}}section{{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}}article{{min-width:0;background:white;border:1px solid #ded8cb;border-radius:12px;padding:14px}}article[hidden]{{display:none}}article img{{width:100%;height:170px;object-fit:contain;background:repeating-conic-gradient(#faf8f2 0% 25%,#ffffff 0% 50%) 50%/16px 16px}}h2{{font-size:15px;font-weight:500}}article p{{font-size:12px;color:#72776b}}.filters label{{min-width:0}}@media print{{article{{break-inside:avoid}}.filters{{display:none}}}}</style><main><p>手账工坊 · 2026-11-12</p><h1>贴纸总览 · {len(items)}张</h1><p>生活主题{new}张原创透明底贴纸：人物动作、天气天象、家务日常、运动健康、宠物日常、拼贴装饰、通勤办公、情绪表情。每张是不同动作、物件或表情，不按换色重复计数。</p><p><a href="atelier.html">三套原创设计 ↗</a> · <a href="../?tab=library">打开素材库</a> · <a href="../?tab=editor">自由拼贴</a> · <a href="STICKERS-2026-11-12.md">使用说明与验证</a> · <a href="craft-guide.html">印章与贴纸效果</a></p><p>点击“去素材库选中”只定位素材，原画布保留；然后点击“加入画布”。支持裁切、白边阴影、半透明叠贴、连续花边和实际尺寸贴纸页。新素材由工坊独立绘制，并非品牌原版图案；这里不声称已收齐所有品牌贴纸。</p><div class="filters"><label>搜索 <input id="search" placeholder="例如：瑜伽、洗衣、小猫"></label><label>主题 <select id="theme">{options}</select></label><label><input id="new-only" type="checkbox"> 只看生活主题</label></div><p id="count" role="status"></p><section>{cards}</section><script>const q=document.querySelector('#search'),t=document.querySelector('#theme'),fresh=document.querySelector('#new-only'),cards=[...document.querySelectorAll('article')];function filter(){{let n=0;for(const card of cards){{card.hidden=!(card.textContent.toLowerCase().includes(q.value.trim().toLowerCase())&&(!t.value||card.dataset.theme===t.value)&&(!fresh.checked||card.dataset.new==='true'));if(!card.hidden)n++;}}document.querySelector('#count').textContent='显示 '+n+' / '+cards.length+' 张贴纸';}}q.oninput=filter;t.onchange=filter;fresh.onchange=filter;filter();</script></main></html>'''
(root/'docs/stickers.html').write_text(html,encoding='utf-8')
print(json.dumps({'stickers':len(items),'new':new}))
